// g1-대기 센서 데이터 처리
// 토픽: smartfarm/wasabi/g1_air_soil/g1-01/air/data
const topicParts = msg.topic.split('/');
const nodeId = topicParts[4]; // g1-01
const data = msg.payload;

// 전역 컨텍스트에 저장
const airData = global.get('airData') || {};
airData[nodeId] = {
    node_id: data.node_id,
    air_temp: data.air_temp,
    air_humidity: data.air_humidity,
    timestamp: data.timestamp,
    rssi: data.rssi,
    updated: new Date()
};
global.set('airData', airData);

// 디버그
node.status({text: `g1-대기: ${nodeId}`});

return msg;

